<?php
declare(strict_types=1);
namespace Workspace;
require __DIR__.'/project_release_unit.php';
$dir=sys_get_temp_dir().'/cw-delivery-'.gkey();mkdir($dir,0700);putenv('WORKSPACE_DATA='.$dir);putenv('WORKSPACE_DB=sqlite');putenv('WORKSPACE_CONFIG');
function deliveryClean(string $dir):void{foreach(new \FilesystemIterator($dir) as $f){if($f->isDir())deliveryClean($f->getPathname());else unlink($f->getPathname());}rmdir($dir);}
try{
$db=database(true);addUser($db,'owner@example.test','Owner','owner','sample-password-only',true);addUser($db,'dev@example.test','Dev','developer','sample-password-only');$owner=organizationUser($db,['id'=>1,'name'=>'Owner']);$dev=organizationUser($db,['id'=>2,'name'=>'Dev']);$p=createProject($db,$owner,gkey(),['title'=>'Project','kind'=>'oss']);$other=createProject($db,$owner,gkey(),['title'=>'Other','kind'=>'internal']);changeMembership($db,$owner,'project',$p,2,true);
$task=createTask($db,$owner,gkey(),$p,['title'=>'Task','result_customer'=>'Owner','acceptance_criteria'=>'CI + <script>']);query($db,"UPDATE tasks SET state='done' WHERE id=?",[$task]);
$repo=insertId($db,'INSERT INTO github_repositories(project_id,repository_id,installation_id,full_name) VALUES(?,?,?,?)',[$p,40,30,'owner/example']);ghManage($db,$owner,$p,'github.link',['task_id'=>$task,'version'=>0,'kind'=>'pull','number'=>7]);
$f=new ReleaseFixture();[$pem]=gpair();$app=new GitHubApp('20',$pem,function($method,$path,$token,$body)use($f){if(str_ends_with($path,'/pulls/8'))return array_replace($f->read('/pulls/7'),['number'=>8]);return $f->http($method,$path,$token,$body);});
$form=['tag'=>'v1','commit_sha'=>$f->sha,'changelog'=>"Notes\nSecond",'artifact_name'=>'app.zip','artifact_sha256'=>$f->digest,'required_checks'=>'Build','responsible_id'=>1,'tasks'=>[$task],'extra_prs'=>[$task=>'8']];$key=gkey();$r=releaseCreate($db,$owner,$p,$key,$form);gcheck(releaseCreate($db,$owner,$p,$key,$form)===$r,'duplicate create');gdeny(fn()=>releaseCreate($db,$owner,$p,$key,array_replace($form,['extra_prs'=>[$task=>'9']])),409,'changed PRs');
releaseInspect($db,$owner,$p,$r,1,false,$app);releaseInspect($db,$owner,$p,$r,2,true,$app);$page=deliveryPage($db,$dev,$p,$r);gcheck($page['deliveryScopes'][0]['verified']&&count($page['deliveryEvidence']['tasks'])===2,'both PRs verified');gdeny(fn()=>deliveryPage($db,$owner,$other,$r),404,'cross project');
$host=insertId($db,"INSERT INTO infra_hosts(organization_id,name,panel_key,panel_target,panel_hash,panel_api,servers_key,servers_target,servers_hash,workspace_uuid,asset_uuid) VALUES(1,'Host','panel',?,?,'v2','servers',?,?,?,?)",[str_repeat('a',64),str_repeat('b',64),str_repeat('c',64),str_repeat('d',64),str_repeat('e',36),str_repeat('f',36)]);$env=insertId($db,"INSERT INTO infra_environments(organization_id,project_id,kind,name) VALUES(1,?,'staging','Staging')",[$p]);$site=insertId($db,"INSERT INTO infra_sites(organization_id,project_id,environment_id,host_id,remote_id,site_name) VALUES(1,?,?,?,1,'example.test')",[$p,$env,$host]);query($db,"INSERT INTO infra_operation_owners VALUES(?,'site.deploy','aapanel',1)",[$host]);
$in=['site_id'=>$site,'release_id'=>$r,'window_start'=>gmdate('Y-m-d\TH:i',time()-60),'window_end'=>gmdate('Y-m-d\TH:i',time()+3600)];$dep=deploymentCreate($db,$owner,$p,gkey(),$in);
$success=fn($job,$recover)=>['state'=>'succeeded','before'=>str_repeat('d',40),'after'=>$job['commit'],'after_digest'=>$job['digest'],'message'=>'Verified'];gcheck(deploymentRun($db,$dep,false,$success)['state']==='succeeded','executor observation');
$page=deliveryPage($db,$dev,$p,$r);$s=$page['deliveryScopes'][0];$siteRow=$page['deliverySites'][0];gcheck($siteRow['matches'],'exact deployment');$review=['task_id'=>$task,'deployment_id'=>$dep,'fingerprint'=>deliveryFingerprint($page['deliveryRelease'],$s,$siteRow['deployment'],null),'outcome'=>'passed','notes'=>"CI checked\nQA checked"];$key=gkey();$qid=deliveryReview($db,$dev,$p,$r,$key,$review);gcheck(deliveryReview($db,$dev,$p,$r,$key,$review)===$qid,'idempotent QA');gdeny(fn()=>deliveryReview($db,$dev,$p,$r,gkey(),$review),409,'stale QA form');
require ROOT.'/app/Web.php';$_SESSION=['csrf'=>'test'];ob_start();pageView('delivery','Delivery',$dev,deliveryPage($db,$dev,$p,$r));$html=ob_get_clean();gcheck(str_contains($html,'&lt;script&gt;')&&str_contains($html,'PR #8')&&str_contains($html,'passed'),'escaped integrated card');
query($db,'UPDATE tasks SET version=version+1 WHERE id=?',[$task]);gcheck(!deliveryPage($db,$dev,$p,$r)['deliveryScopes'][0]['current'],'task edit historical');gdeny(fn()=>deliveryReview($db,$dev,$p,$r,gkey(),$review),409,'edited task blocks QA');
$dep2=deploymentCreate($db,$owner,$p,gkey(),$in);gcheck(!deliveryPage($db,$dev,$p,$r)['deliverySites'][0]['matches'],'new job blocks old observation');
gcheck(deploymentRun($db,$dep2,false,fn($job,$recover)=>['state'=>'succeeded','after'=>$job['commit']])['state']==='recovery_required','missing digest rejected');
gcheck(!deliveryPage($db,$dev,$p,$r)['deliverySites'][0]['matches'],'unknown deployment not accepted');
query($db,'UPDATE github_repositories SET active=0 WHERE id=?',[$repo]);gcheck(deliveryPage($db,$dev,$p,$r)['deliveryEvidence']===null,'repo disabled');
if(in_array('--postgres',$argv,true)){$report=migrateToPostgres($dir.'/source.sqlite');$pg=postgresConnect();gcheck($report['tables']['delivery_reviews']['rows']===1&&count(deliveryPage($pg,$dev,$p,$r)['deliveryScopes'])===1,'Postgres transfer');$pg=null;}
echo "OK · $gh_checks delivery DB checks\n";
}finally{$db=null;deliveryClean($dir);}
